function handleJoinAction(action){if(action==='findInvitation'){const n=document.getElementById('join-code');document.getElementById('join-error').textContent=n.value.trim()?'Invitations are not available until the server is connected.':'Enter an invitation code.';if(!n.value.trim())markFieldInvalid(n);n.focus();return true}if(['requestJoin','simulateApproval','openJoined','viewPending','cancelJoin','declineInvitation'].includes(action)){notice('Sharing requires a server connection.');return true}return false}

