function persistLocal(){
 if(!window.LocalDatabase)return true;
 const result=LocalDatabase.save(JSON.stringify({lists,tasks,state,tracker}));
 if(result!=='ok')state.notice='Could not save. Please keep the app open and try again.';return result==='ok';
}
function restoreLocal(){
 if(!window.LocalDatabase)return;
 const saved=JSON.parse(LocalDatabase.load());
 if(saved&&saved.error){document.getElementById('app').textContent=saved.error;throw new Error(saved.error)}
 if(saved){Object.assign(tracker,{activities:[],customTypes:[]},saved.tracker||{});saved.state=saved.state||{};if(saved.state.attachmentOrderVersion!==1){saved.tasks.forEach(t=>{if(Array.isArray(t.files))t.files.reverse()});saved.state.attachmentOrderVersion=1}lists.splice(0,lists.length,...saved.lists);tasks.splice(0,tasks.length,...saved.tasks);lists.forEach(l=>{l.invitees=l.invitees||[];l.shared=!!l.joined||l.invitees.length>0});Object.assign(state,saved.state,{screen:'home',notice:''});if(!lists.some(l=>l.id===state.list))state.list=lists[0]?.id||'';nextId=Math.max(1,...tasks.map(t=>Number(t.id)+1),...lists.map(l=>Number(l.id.replace('list',''))+1).filter(Number.isFinite));}
}

