async function refreshLists(){if(refreshBusy)return;refreshBusy=true;refreshIndicator('Refreshing…');try{await new Promise(requestAnimationFrame);if(window.LocalDatabase){const saved=JSON.parse(LocalDatabase.load());if(saved?.error)throw Error(saved.error);if(saved){Object.assign(tracker,{activities:[],customTypes:[]},saved.tracker||{});saved.state=saved.state||{};if(saved.state.attachmentOrderVersion!==1){saved.tasks.forEach(t=>{if(Array.isArray(t.files))t.files.reverse()});saved.state.attachmentOrderVersion=1}lists.splice(0,lists.length,...saved.lists);tasks.splice(0,tasks.length,...saved.tasks);lists.forEach(l=>{l.invitees=l.invitees||[];l.shared=!!l.joined||l.invitees.length>0});if(state.list&&!list())state.screen='home'}}clearPull();notice('Local data refreshed · server sync is not connected.')}catch{clearPull();notice('Could not refresh. Try again.')}finally{refreshBusy=false}}
document.addEventListener('touchstart',e=>{const content=e.target.closest('.mobile-content');if(!content||content.scrollTop>0||refreshBusy||taskDrag||!['home','lists','shared','sharedlists','empty'].includes(state.screen)||e.target.closest('[data-drag-task],input,textarea')||e.touches.length!==1)return;pullGesture={x:e.touches[0].clientX,y:e.touches[0].clientY,distance:0}},{passive:true});
document.addEventListener('touchmove',e=>{if(!pullGesture||!e.touches.length)return;const dy=e.touches[0].clientY-pullGesture.y,dx=e.touches[0].clientX-pullGesture.x;if(dy<=0||Math.abs(dx)>dy){clearPull();return}pullGesture.distance=Math.min(90,dy*.5);if(dy>12){e.preventDefault();refreshIndicator(pullGesture.distance>=60?'Release to refresh':'Pull to refresh',pullGesture.distance)}},{passive:false});
