function incompleteClipboard(asTable=false){const l=list(),items=tasks.filter(t=>t.list===l?.id&&!t.done),names=items.map(t=>t.title),headers=['Task Name','Due Date','Tags'],rows=items.map(t=>[t.title,formatDueDate(t.due),t.tags||'']);const cell=(tag,v)=>'<'+tag+' style="border:1px solid #999;padding:6px 10px;white-space:pre-wrap;text-align:left">'+esc(v)+'</'+tag+'>';const html='<html><body><table style="border-collapse:collapse"><thead><tr>'+headers.map(h=>cell('th',h)).join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>cell('td',v)).join('')+'</tr>').join('')+'</tbody></table></body></html>';return {names,text:asTable?[headers,...rows].map(row=>row.map(v=>String(v).replace(/[\t\r\n]+/g,' ')).join('\t')).join('\n'):names.join('\n'),html}}


async function copyIncompleteNames(asTable=false){const {names,text,html}=incompleteClipboard(asTable);if(!names.length){notice('No incomplete tasks to copy');return}try{if(asTable&&window.LocalDatabase?.copyHtml){if(LocalDatabase.copyHtml(text,html)!=='ok')throw Error('Clipboard unavailable')}else if(!asTable&&window.LocalDatabase?.copyText){if(LocalDatabase.copyText(text)!=='ok')throw Error('Clipboard unavailable')}else if(asTable&&navigator.clipboard?.write&&window.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([text],{type:'text/plain'}),'text/html':new Blob([html],{type:'text/html'})})])}else if(!asTable&&navigator.clipboard?.writeText){await navigator.clipboard.writeText(text)}else{const input=document.createElement(asTable?'div':'textarea');if(asTable){input.contentEditable='true';input.innerHTML=html}else input.value=text;input.style.cssText='position:fixed;left:-9999px';document.body.append(input);if(asTable){const range=document.createRange();range.selectNodeContents(input);getSelection().removeAllRanges();getSelection().addRange(range)}else input.select();const copied=document.execCommand('copy');input.remove();getSelection()?.removeAllRanges();if(!copied)throw Error('Clipboard unavailable')}closeCopyOptions();notice(asTable?'Extensive table copied · paste into Excel or email':'Incomplete task names copied')}catch{notice('Could not copy. Please try again.')}}
