document.addEventListener('click',e=>{if(e.target.closest('[data-drag-task]'))return;const row=e.target.closest('.navigation-row,.task-row');if(!row)return;const rect=row.getBoundingClientRect(),effect=document.createElement('div');effect.className='row-tap-effect';effect.style.cssText=`left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;--tap-x:${e.detail?e.clientX-rect.left:rect.width/2}px;--tap-y:${e.detail?e.clientY-rect.top:rect.height/2}px;--tap-size:${Math.hypot(rect.width,rect.height)*2}px`;document.body.append(effect);setTimeout(()=>effect.remove(),320)},true);

const BACKUP_FORMAT_VERSION=2,APP_VERSION='0.46.0';
function buildBackup(){const data=JSON.parse(JSON.stringify({lists,tasks:tasks.map((t,i)=>({...t,sortOrder:i})),tracker,state:{theme:state.theme,notify:state.notify}}));return {metadata:{format:'TaskVillaBackup',formatVersion:BACKUP_FORMAT_VERSION,dataSchemaVersion:4,appName:'TaskVilla',appVersion:APP_VERSION,applicationId:'app.adc.taskvilla',author:'Aniruddha DuttaChowdhury',exportedAt:new Date().toISOString(),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,attachmentStorage:'metadata-only; file bytes excluded',listCount:data.lists.length,taskCount:data.tasks.length,activityCount:tracker.activities.length},data}}
function backupXml(value){const escapeXml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));function element(name,v,attribute=''){const type=v===null?'null':Array.isArray(v)?'array':typeof v;const inner=type==='object'?Object.entries(v).map(([k,val])=>element('field',val,' name="'+escapeXml(k)+'"')).join(''):type==='array'?v.map(item=>element('item',item)).join(''):type==='null'?'':escapeXml(v);return '<'+name+attribute+' type="'+type+'">'+inner+'</'+name+'>'}return '<?xml version="1.0" encoding="UTF-8"?>\n'+element('taskvillaBackup',value)}
function closeExportOptions(){document.querySelector('.export-overlay')?.remove()}
function showExportOptions(){closeExportOptions();const overlay=document.createElement('div');overlay.className='confirm-overlay export-overlay';overlay.innerHTML=`<section class="confirm-dialog export-dialog" role="dialog" aria-modal="true" aria-labelledby="export-title"><div class="palette-header"><h2 id="export-title">Export backup</h2><button class="icon-btn" aria-label="Close export options">×</button></div><p>Export all lists, tasks, personal activities and preferences for a future restore. Choose a format.</p><div class="confirm-actions"><button class="button-primary" data-action="exportJson">${ic('download')} JSON</button><button class="button-primary" data-action="exportXml">${ic('download')} XML</button></div><p class="export-note">Attachment details are included; file contents are not included in this backup.</p></section>`;overlay.querySelector('[aria-label="Close export options"]').onclick=closeExportOptions;overlay.onclick=e=>{if(e.target===overlay)closeExportOptions()};overlay.onkeydown=e=>{if(e.key==='Escape')closeExportOptions();if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.querySelector('.device').append(overlay);overlay.querySelector('[data-action="exportJson"]').focus()}
function exportBackup(format){if(!['json','xml'].includes(format))return;const backup=buildBackup(),content=format==='json'?JSON.stringify(backup,null,2):backupXml(backup),filename='TaskVilla-backup-'+backup.metadata.exportedAt.replace(/[:.]/g,'-')+'.'+format;try{if(window.LocalDatabase?.exportBackup){if(LocalDatabase.exportBackup(filename,content)!=='pending')throw Error('Export unavailable');closeExportOptions()}else{const url=URL.createObjectURL(new Blob([content],{type:format==='json'?'application/json':'application/xml'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);closeExportOptions();notice(format.toUpperCase()+' backup download started')}}catch{notice('Could not export. Please try again.')}}
